/**
 * n8n - Code Node: Normalizar recebimento Seguro Auto
 *
 * Entrada esperada: payload do Google Forms via webhook.
 * Saida: objetos separados para clientes_auto e cotacoes_auto.
 *
 * A busca de campos e tolerante: as chaves do payload sao normalizadas
 * (sem acento, sem pontuacao, minusculas) antes da comparacao, e ha um
 * fallback por palavras-chave. Isso evita o modo de falha silencioso em
 * que uma diferenca de rotulo no Forms ("E-mail" vs "Email (segurado)")
 * gravava NULL no banco sem nenhum erro.
 */

function clean(value) {
  if (value === undefined || value === null) return null;
  if (Array.isArray(value)) return value.filter(Boolean).join(', ') || null;
  const text = String(value).trim();
  return text ? text : null;
}

function onlyDigits(value) {
  const text = clean(value);
  return text ? text.replace(/\D/g, '') : null;
}

function normKey(key) {
  return String(key)
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
}

// Chaves originais do payload que alguma regra conseguiu consumir.
const usados = new Set();

/**
 * Indexa o payload por chave normalizada, preservando a chave original
 * (para o relatorio de campos nao mapeados) e a ordem de insercao.
 */
function buildIndex(body) {
  const index = new Map();
  for (const [key, value] of Object.entries(body)) {
    const norm = normKey(key);
    if (!index.has(norm)) index.set(norm, { key, value });
  }
  return index;
}

/** Casamento exato sobre a chave normalizada. */
function pick(index, aliases) {
  for (const alias of aliases) {
    const entry = index.get(normKey(alias));
    if (!entry) continue;
    const value = clean(entry.value);
    if (value !== null) {
      usados.add(entry.key);
      return value;
    }
  }
  return null;
}

/**
 * Fallback: primeira chave que contenha TODOS os termos exigidos e
 * nenhum dos termos proibidos. Usado quando o rotulo do Forms muda.
 */
function pickLike(index, required, forbidden = []) {
  for (const [norm, entry] of index) {
    if (!required.every(term => norm.includes(normKey(term)))) continue;
    if (forbidden.some(term => norm.includes(normKey(term)))) continue;
    const text = clean(entry.value);
    if (text !== null) {
      usados.add(entry.key);
      return text;
    }
  }
  return null;
}

/** Tenta casamento exato e, se falhar, o fallback por palavras-chave. */
function field(index, aliases, required, forbidden = []) {
  const exact = pick(index, aliases);
  if (exact !== null) return exact;
  return required && required.length ? pickLike(index, required, forbidden) : null;
}

const item = $input.first();
const body = item.json.body || item.json;
const index = buildIndex(body);

const CONDUTOR = ['condutor'];

const nomeCliente = field(
  index,
  ['Nome completo (segurado)', 'Nome completo do segurado', 'Nome completo', 'Segurado', 'Nome'],
  ['nome'],
  CONDUTOR,
);

const cpfCliente = onlyDigits(field(
  index,
  ['CPF (segurado)', 'CPF do segurado', 'CPF'],
  ['cpf'],
  CONDUTOR,
));

if (!cpfCliente) {
  // Lista as chaves recebidas para que o erro na execucao do n8n seja
  // diagnosticavel sem precisar reabrir o Forms.
  throw new Error(
    'CPF do segurado e obrigatorio para registrar cotacao AUTO. Campos recebidos: '
    + Object.keys(body).join(' | '),
  );
}

const cliente = {
  nome_completo: nomeCliente || cpfCliente,
  cpf: cpfCliente,
  telefone: field(index, ['Telefone (segurado)', 'Telefone'], ['telefone'], [...CONDUTOR, 'celular']),
  celular: field(
    index,
    ['Celular (segurado)', 'Celular do segurado', 'Celular', 'WhatsApp'],
    ['celular'],
    CONDUTOR,
  ) || pickLike(index, ['whatsapp'], CONDUTOR),
  email: field(
    index,
    ['Email (segurado)', 'E-mail (segurado)', 'Email', 'E-mail'],
    ['email'],
    CONDUTOR,
  ),
  estado_civil: field(index, ['Estado civil'], ['estado civil'], CONDUTOR),
  profissao: field(index, ['Profissao', 'Profissão'], ['profissao'], CONDUTOR),
};

const tipoResidencia = field(
  index,
  ['Tipo de residencia', 'Tipo de residência'],
  ['tipo', 'residencia'],
);

const passagemLeilao = field(
  index,
  [
    'Veiculo tem passagem por leilao',
    'Veículo tem passagem por leilão',
    'Veiculo possui passagem por leilao',
    'Veículo possui passagem por leilão',
    'Passagem por leilao',
    'Passagem por leilão',
  ],
  ['leilao'],
);

const cotacao = {
  tipo: 'novo',
  origem_lead: field(index, ['Origem do lead', 'Origem', 'Canal', 'Indicação'], ['origem']) || 'forms',
  nome_cliente: cliente.nome_completo,
  cpf_cliente: cliente.cpf,
  celular_cliente: cliente.celular,
  email_cliente: cliente.email,
  estado_civil_cliente: cliente.estado_civil,
  profissao_cliente: cliente.profissao,
  condutor_nome: field(
    index,
    ['Nome completo (condutor principal)', 'Nome completo do condutor principal', 'Condutor principal'],
    ['nome', 'condutor'],
  ),
  condutor_cpf: onlyDigits(field(
    index,
    ['CPF (condutor principal)', 'CPF do condutor principal', 'CPF condutor'],
    ['cpf', 'condutor'],
  )),
  estado_civil_condutor: field(
    index,
    ['Estado civil do condutor', 'Estado civil do condutor principal'],
    ['estado civil', 'condutor'],
  ),
  cep_pernoite: field(index, ['Cep de pernoite', 'CEP de pernoite', 'CEP pernoite'], ['cep']),
  uso_veiculo: field(index, ['Uso do veiculo', 'Uso do veículo'], ['uso', 'veiculo']),
  garagem_residencia: field(index, ['Garagem na residencia', 'Garagem na residência'], ['garagem', 'residencia']),
  garagem_trabalho: field(index, ['Garagem no trabalho'], ['garagem', 'trabalho']),
  garagem_estudo: field(index, ['Garagem no estudo'], ['garagem', 'estudo']),
  jovens_18_26: field(
    index,
    [
      'Existe jovens de 18 a 26 anos que more e use o veiculo',
      'Existe jovens de 18 a 26 anos que more e use o veículo',
      'Jovens 18 a 26',
    ],
    ['18'],
  ),
  modelo_veiculo: field(
    index,
    ['Modelo do veiculo (marca/ano)', 'Modelo do veículo (marca/ano)', 'Modelo do veiculo', 'Modelo do veículo'],
    ['modelo'],
  ),
  placa: field(index, ['Placa'], ['placa']),
  veiculo_financiado: field(index, ['Veiculo financiado', 'Veículo financiado'], ['financiado']),
  possui_kit_gas: field(index, ['Possui kit gas', 'Possui kit gás'], ['kit gas']),
  possui_blindagem: field(index, ['Possui blindagem'], ['blindagem']),
  isento_imposto: field(
    index,
    ['E isento de imposto', 'É isento de imposto', 'Isento de imposto'],
    ['isento'],
  ),
  status: 'aberta',
};

// Chaves do payload que nao foram consumidas por nenhuma regra. Ficam
// visiveis na execucao para que um campo novo do Forms nao passe despercebido.
// Campos vazios no Forms nao contam como perda de dado.
const campos_nao_mapeados = Object.keys(body)
  .filter(key => !usados.has(key) && clean(body[key]) !== null);

return [{
  json: {
    cliente,
    cotacao,
    raw_data: { ...body, _conves: { tipo_residencia: tipoResidencia, passagem_leilao: passagemLeilao } },
    campos_nao_mapeados,
    formulario: field(index, ['formulario', 'Formulário'], ['formulario']) || 'Seguro Auto',
    recebido_em: clean(body.timestamp) || new Date().toISOString(),
  },
}];
